"""Provisioning regressions using tiny generated bytes, never model tensors."""
import contextlib
import copy
import hashlib
import importlib.util
import io
import json
import os
from pathlib import Path
import stat
import tempfile
import unittest
from unittest.mock import patch

REPOSITORY = Path(__file__).resolve().parents[1]
SPEC = importlib.util.spec_from_file_location("configure_meld_media", REPOSITORY / "scripts/configure_meld_media.py")
helper = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(helper)


@unittest.skipUnless(os.name == "posix" and hasattr(os, "O_NOFOLLOW"), "private Linux runtime profile")
class ConfigureMeldMediaTests(unittest.TestCase):
    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory()
        self.addCleanup(self.temporary.cleanup)
        self.root = Path(self.temporary.name)
        self.generation = self.root / "models/generation"
        self.review = self.root / "models/review"
        self.catalog = self.root / "repository/runtimes/meld/catalog"
        self.catalog.mkdir(parents=True)
        self.generation.mkdir(parents=True)
        self.review.mkdir(parents=True)
        self.safe = self.root / "safe"
        self.safe.mkdir()
        self.documents = {}
        self.raw = {}
        self._catalog("generation", self.generation, ["weights.fixture"], False)
        self._catalog("review", self.review, ["language.fixture", "projector.fixture"], True)
        self.addCleanup(patch.stopall)
        patch.object(helper, "ROOT", self.root / "repository").start()
        fixture_hashes = frozenset(a["model"]["sha256"] for a in self.documents["review"]["artifacts"])
        patch.object(helper, "GEMMA_DISCLOSURE_HASHES", fixture_hashes).start()

    def _catalog(self, name, model_root, filenames, disclosed):
        workload = "image-review" if disclosed else "image-generation"
        artifacts = []
        for filename in filenames:
            content = ("Generated tensor-free protocol fixture: " + name + "/" + filename).encode()
            (model_root / filename).write_bytes(content)
            provenance = {"publisher": "Example Fixture Lab", "country": "US",
                          "evidence": ["https://example.org/fictional-protocol-fixture"],
                          "lineage_complete": not disclosed, "base_models": []}
            if disclosed:
                provenance["lineage_disclosure"] = "publisher-disclosed"
            artifacts.append({"path": filename, "model": {
                "id": name + "/" + filename, "revision": "generated-fixture-1",
                "source": "https://example.org/fixture/" + filename,
                "license": "fixture-only", "format": "fixture", "runtime": "fixture",
                "sha256": hashlib.sha256(content).hexdigest(), "size_bytes": len(content),
                "workloads": [workload], "provenance": provenance}})
        document = {"schema_version": 1, "runtime_version": "tensor-free-protocol-fixture",
                    "backend": "llama_cpp_vlm" if disclosed else "sdxl_img2img",
                    "workload": workload, "model": name + "-fixture",
                    "artifact_set_complete": True, "artifacts": artifacts}
        raw = (json.dumps(document, indent=2) + "\n").encode()
        filename = "gemma-3-4b-it-q4-k-m.json" if disclosed else "sdxl-base-1.0-fp16.json"
        (self.catalog / filename).write_bytes(raw)
        self.documents[name] = document
        self.raw[name] = raw

    def _invoke(self, output, generation=None, review=None, accept=True, catalog=None, queue=None):
        args = ["configure_meld_media.py", "--generation-root", str(generation or self.generation),
                "--review-root", str(review or self.review), "--output", str(output),
                "--review-note", "Owner accepts only these exact fictional fixture artifacts."]
        if accept:
            args.append("--accept-google-published-lineage")
        if catalog is not None:
            args.extend(["--generation-catalog", catalog])
        if queue is not None:
            args.extend(["--queue-connection", queue])
        with patch("sys.argv", args), contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()):
            helper.main()

    def _tree(self):
        return {str(path.relative_to(self.root)): path.read_bytes() if path.is_file() else None
                for path in self.root.rglob("*")}

    def test_dotdot_containment_is_rejected_before_any_profile_or_hash_work(self):
        spelling = self.root / "models/spelling"
        spelling.mkdir()
        cases = [
            (self.safe / "../models/generation/profile", self.generation, self.review),
            (self.generation / "profile", spelling / "../generation", self.review),
            (self.review / "profile", self.generation, spelling / "../review"),
        ]
        for output, generation, review in cases:
            with self.subTest(output=str(output), generation=str(generation), review=str(review)):
                before = self._tree()
                with patch.object(helper.VerifiedManifest, "load") as loader, patch.object(helper, "write_private") as writer:
                    with self.assertRaises(SystemExit) as error:
                        self._invoke(output, generation, review)
                    self.assertEqual(error.exception.code, 2)
                    loader.assert_not_called()
                    writer.assert_not_called()
                self.assertEqual(self._tree(), before)
                self.assertFalse(output.resolve().exists())

    def test_sibling_profile_uses_canonical_paths_private_files_and_exact_approvals(self):
        spelled = self.safe / "../profile"
        output = spelled.resolve()
        self._invoke(spelled)
        self.assertEqual(stat.S_IMODE(output.stat().st_mode), 0o700)
        self.assertEqual(len(list(output.iterdir())), 8)
        for path in output.iterdir():
            self.assertEqual(stat.S_IMODE(path.stat().st_mode), 0o600, path.name)
        owner = json.loads((output / "owner.json").read_bytes())
        profile = json.loads((output / "profile.json").read_bytes())
        self.assertEqual(profile["shared_lock"], str(output / "node-execution.lock"))
        self.assertEqual(profile["generation_root"], str(self.generation.resolve()))
        self.assertEqual(profile["review_root"], str(self.review.resolve()))
        approvals = {entry["sha256"]: entry for entry in owner["approved_models"]}
        self.assertEqual(len(approvals), 3)
        for name, document in self.documents.items():
            self.assertEqual((output / (name + "-manifest.json")).read_bytes(), self.raw[name])
            expected_pin = hashlib.sha256(self.raw[name]).hexdigest()
            self.assertEqual(owner["meld"][name + "_manifest_sha256"], expected_pin)
            self.assertEqual(profile[name + "_manifest_sha256"], expected_pin)
            for artifact in document["artifacts"]:
                approved = approvals[artifact["model"]["sha256"]]
                self.assertEqual(approved["provenance"], artifact["model"]["provenance"])
                if name == "review":
                    self.assertIs(approved["allow_publisher_disclosed_lineage"], True)
                    self.assertTrue(approved["review_note"])
                    self.assertIs(approved["provenance"]["lineage_complete"], False)
                else:
                    self.assertNotIn("allow_publisher_disclosed_lineage", approved)
        self.assertNotIn("allow_publisher_disclosed_lineage", owner)
        self.assertNotIn("allow_publisher_disclosed_lineage", owner["meld"])
        tokens = [(output / (name + "-token")).read_text().strip() for name in ["owner", "generation", "review"]]
        self.assertEqual(len(set(tokens)), 3)
        self.assertEqual(owner["api_key"], tokens[0])
        self.assertIn("NUCLEUS_INFERENCE_API_KEY=" + tokens[0], (output / "meld.env").read_text())

    def test_explicit_queue_and_quoted_negative_prompt_have_fixed_private_values(self):
        output = self.root / "queue-profile"
        self._invoke(output, queue="nucleus-media")
        raw = (output / "meld.env").read_text()
        self.assertIn("IMAGE_GENERATION_QUEUE_CONNECTION=nucleus-media\n", raw)
        self.assertIn('POSITRONIC_IMAGE_NEGATIVE_PROMPT="' + helper.BASELINE_NEGATIVE_PROMPT + '"\n', raw)
        self.assertIn("IMAGE_REVIEW_SOFT_ACCEPT=false\n", raw)
        self.assertIn("POSITRONIC_IMAGE_MAX_PIXELS=262144\n", raw)
        for setting in ["POSITRONIC_IMAGE_STEPS=30", "POSITRONIC_IMAGE_GUIDANCE_SCALE=5", "IMAGE_REVIEW_MAX_ATTEMPTS=1", "POSITRONIC_IMAGE_TIMEOUT=1800", "POSITRONIC_IMAGE_REVIEW_TIMEOUT=600", 'POSITRONIC_IMAGE_REVIEW_RETRY_DELAYS_MS=""']:
            self.assertIn(setting + "\n", raw)
        self.assertEqual(stat.S_IMODE((output / "meld.env").stat().st_mode), 0o600)
        owner = json.loads((output / "owner.json").read_text())
        expected = {artifact["model"]["sha256"] for artifact in self.documents["review"]["artifacts"]}
        self.assertEqual({entry["sha256"] for entry in owner["approved_models"] if entry.get("allow_publisher_disclosed_lineage")}, expected)

    def test_selected_readout_catalog_preserves_distinct_backend_and_exact_head_scope(self):
        manifest = copy.deepcopy(self.documents["generation"])
        manifest["backend"] = "sdxl_readout"
        manifest["model"] = "readout-fixture"
        hashes = set()
        for name in ["appearance.fixture", "pose.fixture"]:
            content = ("Generated readout protocol fixture: " + name).encode()
            (self.generation / name).write_bytes(content)
            artifact = copy.deepcopy(manifest["artifacts"][0])
            artifact["path"] = name
            model = artifact["model"]
            model["id"] = "readout-fixture/" + name
            model["sha256"] = hashlib.sha256(content).hexdigest()
            model["size_bytes"] = len(content)
            model["provenance"]["lineage_complete"] = False
            model["provenance"]["lineage_disclosure"] = "publisher-disclosed"
            manifest["artifacts"].append(artifact)
            hashes.add(model["sha256"])
        raw = (json.dumps(manifest, indent=2) + "\n").encode()
        (self.catalog / "sdxl-readout-guidance.json").write_bytes(raw)
        output = self.root / "readout-profile"
        with patch.object(helper, "READOUT_DISCLOSURE_HASHES", frozenset(hashes)):
            self._invoke(output, catalog="sdxl-readout-guidance")
        owner = json.loads((output / "owner.json").read_bytes())
        profile = json.loads((output / "profile.json").read_bytes())
        self.assertEqual(profile["generation_backend"], "sdxl_readout")
        self.assertEqual(profile["generation_model"], "readout-fixture")
        self.assertEqual((output / "generation-manifest.json").read_bytes(), raw)
        self.assertEqual(profile["generation_manifest_sha256"], hashlib.sha256(raw).hexdigest())
        self.assertIn("POSITRONIC_IMAGE_BACKEND=sdxl_readout", (output / "meld.env").read_text())
        approvals = {entry["sha256"]: entry for entry in owner["approved_models"]}
        self.assertEqual(len(approvals), 5)
        for digest in hashes:
            self.assertIs(approvals[digest]["allow_publisher_disclosed_lineage"], True)
            self.assertIs(approvals[digest]["provenance"]["lineage_complete"], False)
        base_hash = manifest["artifacts"][0]["model"]["sha256"]
        self.assertNotIn("allow_publisher_disclosed_lineage", approvals[base_hash])
        self.assertNotIn("allow_publisher_disclosed_lineage", owner)

    def test_unknown_disclosed_artifact_cannot_receive_generic_google_exception(self):
        before = self._tree()
        with patch.object(helper, "GEMMA_DISCLOSURE_HASHES", frozenset()):
            with self.assertRaises(SystemExit) as error:
                self._invoke(self.root / "profile")
        self.assertEqual(error.exception.code, 2)
        self.assertEqual(self._tree(), before)

    def test_missing_explicit_disclosure_acceptance_writes_nothing(self):
        before = self._tree()
        with self.assertRaises(SystemExit):
            self._invoke(self.root / "profile", accept=False)
        self.assertEqual(self._tree(), before)


if __name__ == "__main__":
    unittest.main()
